add_filter( 'the_content', 'perfectpixel_related_posts_by_category', 20 );

function perfectpixel_related_posts_by_category( $content ) {
	if ( ! is_singular( 'post' ) || ! in_the_loop() || ! is_main_query() ) {
		return $content;
	}
	$post_id = get_the_ID();
	$cats    = wp_get_post_categories( $post_id );
	if ( ! $cats ) {
		return $content;
	}
	$related = get_posts(
		array(
			'category__in'           => $cats,
			'post__not_in'           => array( $post_id ),
			'posts_per_page'         => max( 1, (int) '{{related_posts_count}}' ),
			'ignore_sticky_posts'    => true,
			'no_found_rows'          => true,
			'update_post_meta_cache' => false,
		)
	);
	if ( ! $related ) {
		return $content;
	}
	$html = '<div class="perfectpixel-related-posts"><h3>' . esc_html( '{{related_posts_heading}}' ) . '</h3><ul>';
	foreach ( $related as $post ) {
		$html .= '<li><a href="' . esc_url( get_permalink( $post ) ) . '">' . esc_html( get_the_title( $post ) ) . '</a></li>';
	}
	return $content . $html . '</ul></div>';
}
